<?php
require dirname(__DIR__) . '/app/bootstrap.php';
$page = $_GET['page'] ?? (user() ? 'dashboard' : 'login');
$managerPages = ['fleet','people','assignments','maintenance','fuel','alerts'];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    try {
        $pdo = db();
        switch ($_POST['action'] ?? '') {
            case 'register':
                $orgName=trim($_POST['org_name'] ?? '');
                $name=trim($_POST['name'] ?? '');
                $email=strtolower(trim($_POST['email'] ?? ''));
                $password=$_POST['password'] ?? '';
                if ($orgName==='' || strlen($orgName)>150 || $name==='' || strlen($name)>100 || !filter_var($email,FILTER_VALIDATE_EMAIL)) throw new RuntimeException('Enter a valid organization name, full name, and email address.');
                if (strlen($password)<12) throw new RuntimeException('Use a password with at least 12 characters.');
                if (!hash_equals($password,$_POST['password_confirm'] ?? '')) throw new RuntimeException('The passwords do not match.');
                $q=$pdo->prepare('SELECT COUNT(*) FROM users WHERE email=?'); $q->execute([$email]);
                if ($q->fetchColumn()) throw new RuntimeException('That email already has an account. Sign in or use another email.');
                $orgId=uid(); $pdo->beginTransaction();
                $pdo->prepare('INSERT INTO organizations (id,name) VALUES (?,?)')->execute([$orgId,$orgName]);
                $pdo->prepare('INSERT INTO users (id,org_id,name,email,password_hash,role) VALUES (?,?,?,?,?,?)')->execute([uid(),$orgId,$name,$email,password_hash($password,PASSWORD_DEFAULT),'FLEET_MANAGER']);
                $pdo->commit(); notice('Your organization workspace is ready. Sign in with your new account.'); redirect('login');
            case 'login':
                $q=$pdo->prepare('SELECT id,org_id,name,email,password_hash,role FROM users WHERE email=?'); $q->execute([strtolower(trim($_POST['email'] ?? ''))]); $u=$q->fetch();
                if (!$u || !password_verify($_POST['password'] ?? '', $u['password_hash'])) throw new RuntimeException('Email or password is incorrect.');
                session_regenerate_id(true); unset($u['password_hash']); $_SESSION['user']=$u; redirect('dashboard');
            case 'logout': $_SESSION=[]; session_destroy(); header('Location: ?page=login'); exit;
            case 'vehicle_save':
                require_role('FLEET_MANAGER');
                $id=trim($_POST['id'] ?? ''); $values=[trim($_POST['plate_number'] ?? ''),trim($_POST['model'] ?? ''),(int)($_POST['year'] ?? 0),trim($_POST['fuel_type'] ?? ''),$_POST['status'] ?? 'ACTIVE',(int)($_POST['current_odometer'] ?? 0),$_POST['insurance_expiry'] ?: null,$_POST['revenue_lic_expiry'] ?: null];
                if (!$values[0] || !$values[1] || $values[2]<1980 || $values[2]>(int)date('Y')+1 || $values[7] && !strtotime($values[7])) throw new RuntimeException('Check the vehicle details and try again.');
                if ($id) { $current=scoped_vehicle($id); if($values[5]<(int)$current['current_odometer']) throw new RuntimeException('Odometer cannot be lower than the current reading.'); if($values[4]==='ACTIVE' && in_array($current['status'],['IN_MAINTENANCE'],true)) { $check=$pdo->prepare("SELECT COUNT(*) FROM job_cards WHERE vehicle_id=? AND status IN ('OPEN','IN_PROGRESS')"); $check->execute([$id]); if($check->fetchColumn()) throw new RuntimeException('Complete or cancel open maintenance jobs before making this vehicle available.'); } $q=$pdo->prepare('UPDATE vehicles SET plate_number=?,model=?,year=?,fuel_type=?,status=?,current_odometer=?,insurance_expiry=?,revenue_lic_expiry=? WHERE id=? AND org_id=?'); $q->execute([...$values,$id,user()['org_id']]); }
                else { $q=$pdo->prepare('INSERT INTO vehicles (id,org_id,plate_number,model,year,fuel_type,status,current_odometer,insurance_expiry,revenue_lic_expiry) VALUES (?,?,?,?,?,?,?,?,?,?)'); $q->execute([uid(),user()['org_id'],...$values]); }
                notice('Vehicle saved.'); redirect('fleet');
            case 'vehicle_retire': require_role('FLEET_MANAGER'); scoped_vehicle($_POST['id']); $pdo->prepare("UPDATE vehicles SET status='RETIRED' WHERE id=? AND org_id=?")->execute([$_POST['id'],user()['org_id']]); notice('Vehicle retired.'); redirect('fleet');
            case 'person_save': require_role('FLEET_MANAGER');
                $role=$_POST['role'] ?? ''; if(!in_array($role,['DRIVER','MECHANIC'],true)) throw new RuntimeException('Choose a valid team role.');
                if(strlen($_POST['password'] ?? '')<12) throw new RuntimeException('Temporary passwords must be at least 12 characters.');
                $q=$pdo->prepare('INSERT INTO users (id,org_id,name,email,password_hash,role) VALUES (?,?,?,?,?,?)'); $q->execute([uid(),user()['org_id'],trim($_POST['name']),strtolower(trim($_POST['email'])),password_hash($_POST['password'],PASSWORD_DEFAULT),$role]); notice('Team member added.'); redirect('people');
            case 'assignment_save': require_role('FLEET_MANAGER');
                $v=scoped_vehicle($_POST['vehicle_id']); if($v['status']!=='ACTIVE') throw new RuntimeException('Only active vehicles can be assigned.');
                $check=$pdo->prepare("SELECT COUNT(*) FROM users WHERE id=? AND org_id=? AND role='DRIVER'"); $check->execute([$_POST['driver_id'],user()['org_id']]); if(!$check->fetchColumn()) throw new RuntimeException('Choose a driver from your organization.');
                $start=str_replace('T',' ',$_POST['shift_start'] ?? ''); $end=str_replace('T',' ',$_POST['shift_end'] ?? ''); if(strtotime($end)<=strtotime($start)) throw new RuntimeException('Shift end must be after its start.');
                $q=$pdo->prepare("SELECT COUNT(*) FROM assignments a JOIN vehicles v ON v.id=a.vehicle_id JOIN users d ON d.id=a.driver_id WHERE v.org_id=? AND (a.vehicle_id=? OR a.driver_id=?) AND a.shift_start < ? AND a.shift_end > ?"); $q->execute([user()['org_id'],$_POST['vehicle_id'],$_POST['driver_id'],$end,$start]); if($q->fetchColumn()) throw new RuntimeException('That vehicle or driver already has an overlapping shift.');
                $q=$pdo->prepare('INSERT INTO assignments (id,vehicle_id,driver_id,shift_start,shift_end) VALUES (?,?,?,?,?)'); $q->execute([uid(),$_POST['vehicle_id'],$_POST['driver_id'],$start,$end]); notice('Shift assigned.'); redirect('assignments');
            case 'job_save': require_role('FLEET_MANAGER','MECHANIC');
                $v=scoped_vehicle($_POST['vehicle_id']);
                if(trim($_POST['title'] ?? '')==='') throw new RuntimeException('Enter a job title.');
                if((float)($_POST['labor_cost'] ?? 0)<0) throw new RuntimeException('Labor cost cannot be negative.');
                if(!in_array($_POST['status'] ?? 'OPEN',['OPEN','IN_PROGRESS'],true)) throw new RuntimeException('Choose a valid starting status.');
                if(can('MECHANIC')) $_POST['mechanic_id']=user()['id'];
                if(!empty($_POST['mechanic_id'])) { $check=$pdo->prepare("SELECT COUNT(*) FROM users WHERE id=? AND org_id=? AND role='MECHANIC'"); $check->execute([$_POST['mechanic_id'],user()['org_id']]); if(!$check->fetchColumn()) throw new RuntimeException('Choose a mechanic from your organization.'); }
                if(!empty($_POST['service_rule_id'])) { $check=$pdo->prepare('SELECT COUNT(*) FROM service_rules sr JOIN vehicles v ON v.id=sr.vehicle_id WHERE sr.id=? AND sr.vehicle_id=? AND v.org_id=?'); $check->execute([$_POST['service_rule_id'],$v['id'],user()['org_id']]); if(!$check->fetchColumn()) throw new RuntimeException('Choose a service rule for this vehicle.'); }
                $pdo->beginTransaction();
                $jobId=uid(); $q=$pdo->prepare('INSERT INTO job_cards (id,vehicle_id,mechanic_id,service_rule_id,title,description,status,labor_cost) VALUES (?,?,?,?,?,?,?,?)'); $q->execute([$jobId,$v['id'],$_POST['mechanic_id'] ?: null,$_POST['service_rule_id'] ?: null,trim($_POST['title']),trim($_POST['description']),$_POST['status'] ?? 'OPEN',(float)($_POST['labor_cost'] ?? 0)]);
                if(trim($_POST['part_name'] ?? '')!=='') { $qty=(int)($_POST['part_quantity'] ?? 1); $cost=(float)($_POST['part_cost'] ?? 0); if($qty<1||$cost<0) throw new RuntimeException('Enter a valid part quantity and unit cost.'); $pdo->prepare('INSERT INTO job_parts (id,job_card_id,name,quantity,unit_cost) VALUES (?,?,?,?,?)')->execute([uid(),$jobId,trim($_POST['part_name']),$qty,$cost]); }
                if (in_array($_POST['status'] ?? 'OPEN',['OPEN','IN_PROGRESS'],true)) $pdo->prepare("UPDATE vehicles SET status='IN_MAINTENANCE' WHERE id=? AND org_id=?")->execute([$v['id'],user()['org_id']]); $pdo->commit(); notice('Job card created.'); redirect('maintenance');
            case 'job_status': require_role('FLEET_MANAGER','MECHANIC');
                $sql='SELECT j.id,j.vehicle_id,v.org_id FROM job_cards j JOIN vehicles v ON v.id=j.vehicle_id WHERE j.id=? AND v.org_id=?'; $params=[$_POST['id'],user()['org_id']]; if(can('MECHANIC')) { $sql.=' AND j.mechanic_id=?'; $params[]=user()['id']; } $q=$pdo->prepare($sql); $q->execute($params); $job=$q->fetch(); if(!$job) throw new RuntimeException('Job card not found or not assigned to you.');
                $status=$_POST['status']; if(!in_array($status,['IN_PROGRESS','COMPLETED','CANCELLED'],true)) throw new RuntimeException('Invalid job status.'); $pdo->beginTransaction();
                $pdo->prepare('UPDATE job_cards SET status=?, completed_at=IF(?="COMPLETED",CURRENT_TIMESTAMP,NULL) WHERE id=?')->execute([$status,$status,$job['id']]);
                if($status==='COMPLETED') { $pdo->prepare("UPDATE vehicles SET status='ACTIVE' WHERE id=? AND org_id=?")->execute([$job['vehicle_id'],user()['org_id']]); $pdo->prepare('UPDATE service_rules sr JOIN vehicles v ON v.id=sr.vehicle_id SET sr.last_service_odometer=v.current_odometer WHERE sr.id=(SELECT service_rule_id FROM job_cards WHERE id=?) AND v.org_id=?')->execute([$job['id'],user()['org_id']]); }
                elseif($status==='CANCELLED') $pdo->prepare("UPDATE vehicles SET status='ACTIVE' WHERE id=? AND org_id=? AND NOT EXISTS (SELECT 1 FROM job_cards WHERE vehicle_id=? AND status IN ('OPEN','IN_PROGRESS'))")->execute([$job['vehicle_id'],user()['org_id'],$job['vehicle_id']]); $pdo->commit(); notice('Job status updated.'); redirect('maintenance');
            case 'fuel_save': require_role('FLEET_MANAGER','DRIVER');
                $v=scoped_vehicle($_POST['vehicle_id']); $odo=(int)$_POST['odometer']; if($odo<$v['current_odometer']) throw new RuntimeException('Odometer must not be lower than the current reading.');
                if((float)($_POST['liters']??0)<=0 || (float)($_POST['total_cost']??-1)<0) throw new RuntimeException('Enter valid fuel quantity and cost.');
                $driver=can('DRIVER')?user()['id']:($_POST['driver_id'] ?: user()['id']); $check=$pdo->prepare('SELECT COUNT(*) FROM users WHERE id=? AND org_id=?'); $check->execute([$driver,user()['org_id']]); if(!$check->fetchColumn()) throw new RuntimeException('Choose a team member from your organization.'); $pdo->beginTransaction(); $pdo->prepare('INSERT INTO fuel_logs (id,vehicle_id,driver_id,odometer,liters,total_cost,full_tank) VALUES (?,?,?,?,?,?,?)')->execute([uid(),$v['id'],$driver,$odo,(float)$_POST['liters'],(float)$_POST['total_cost'],isset($_POST['full_tank'])]); $pdo->prepare('UPDATE vehicles SET current_odometer=? WHERE id=? AND org_id=?')->execute([$odo,$v['id'],user()['org_id']]); $pdo->commit(); notice('Fuel entry recorded.'); redirect('fuel');
            case 'alert_resolve': require_role('FLEET_MANAGER'); $pdo->prepare('UPDATE alerts SET resolved=1 WHERE id=? AND org_id=?')->execute([$_POST['id'],user()['org_id']]); notice('Alert resolved.'); redirect('alerts');
            case 'rule_save': require_role('FLEET_MANAGER'); $v=scoped_vehicle($_POST['vehicle_id']); if(trim($_POST['name']??'')===''||(int)($_POST['interval_km']??0)<1||(int)($_POST['last_service_odometer']??-1)<0) throw new RuntimeException('Enter a name, positive service interval, and valid odometer.'); $pdo->prepare('INSERT INTO service_rules (id,vehicle_id,name,interval_km,last_service_odometer) VALUES (?,?,?,?,?)')->execute([uid(),$v['id'],trim($_POST['name']),(int)$_POST['interval_km'],(int)$_POST['last_service_odometer']]); notice('Service rule added.'); redirect('maintenance');
        }
    } catch (Throwable $ex) {
        if (isset($pdo) && $pdo->inTransaction()) $pdo->rollBack();
        if ($ex instanceof PDOException) {
            $sqlState=$ex->errorInfo[0] ?? $ex->getCode();
            $message=$sqlState==='23000' ? 'That email is already registered. Sign in or use another email.' : friendly_db_error($ex);
        } else $message=$ex->getMessage();
        notice($message, 'error'); redirect($page);
    }
}

if (in_array($page,['login','signup'],true)) { if(user()) redirect('dashboard'); auth_page($page); exit; }
$me=require_login(); if(in_array($page,$managerPages,true) && $page==='people' && !can('FLEET_MANAGER')) { http_response_code(403); $page='forbidden'; }
try { $pdo=db(); } catch(Throwable $ex) { $dbError='Database is not connected. Configure .env using the README setup steps.'; }
function rows(string $sql, array $params=[]): array { $q=db()->prepare($sql); $q->execute($params); return $q->fetchAll(); }
function one(string $sql, array $params=[]): array { $q=db()->prepare($sql); $q->execute($params); return $q->fetch() ?: []; }
function auth_page(string $mode): void { $signup=$mode==='signup'; ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=$signup?'Create workspace':'Sign in'?> · FleetOps</title><link rel="stylesheet" href="assets/app.css"></head><body class="login-body"><main class="login-card"><img src="assets/fleetops-logo.svg" class="brand-logo" alt="FleetOps"><p class="eyebrow">FLEET OPERATIONS</p><h1><?=$signup?'Create your workspace':'Welcome back'?></h1><p class="muted"><?=$signup?'Set up an organization and its manager account.':'Sign in to manage your fleet.'?></p><?php render_notice(); ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="<?=$signup?'register':'login'?>"><?php if($signup): ?><label>Organization name<input name="org_name" maxlength="150" required autocomplete="organization"></label><label>Your full name<input name="name" maxlength="100" required autocomplete="name"></label><?php endif; ?><label>Email address<input type="email" name="email" required autocomplete="username"></label><label>Password<input type="password" name="password" required minlength="12" autocomplete="<?=$signup?'new-password':'current-password'?>"></label><?php if($signup): ?><label>Confirm password<input type="password" name="password_confirm" required minlength="12" autocomplete="new-password"></label><?php endif; ?><button class="button primary wide"><?=$signup?'Create workspace':'Sign in'?> <span>→</span></button></form><p class="auth-switch"><?=$signup?'Already have a workspace? <a href="?page=login">Sign in</a>':'New to FleetOps? <a href="?page=signup">Create an organization</a>'?></p><p class="login-foot">Each organization has a separate workspace</p></main></body></html><?php }
function render_notice(): void { if(!empty($_SESSION['notice'])) { [$m,$k]=$_SESSION['notice']; unset($_SESSION['notice']); echo '<div class="notice '.e($k).'">'.e($m).'</div>'; } }
function start_form(string $action): void { echo '<form method="post" class="inline-form"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="'.e($action).'">'; }
function vehicle_options(array $vehicles, ?string $selected=null): void { foreach($vehicles as $v) echo '<option value="'.e($v['id']).'" '.($selected===$v['id']?'selected':'').'>'.e($v['plate_number'].' · '.$v['model']).'</option>'; }
$vehicles=[]; $drivers=[]; $mechanics=[]; $alertsCount=0;
if(isset($dbError)) { $vehicles=[]; $orgName='FleetOps'; } else {
 $orgName=one('SELECT name FROM organizations WHERE id=?',[user()['org_id']])['name'] ?? 'FleetOps';
 $vehicles=rows('SELECT * FROM vehicles WHERE org_id=? AND deleted_at IS NULL ORDER BY plate_number',[user()['org_id']]);
 $drivers=rows("SELECT id,name,email FROM users WHERE org_id=? AND role='DRIVER' ORDER BY name",[user()['org_id']]);
 $mechanics=rows("SELECT id,name,email FROM users WHERE org_id=? AND role='MECHANIC' ORDER BY name",[user()['org_id']]);
 $alertsCount=(int)one('SELECT COUNT(*) n FROM alerts WHERE org_id=? AND resolved=0',[user()['org_id']])['n'];
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e(ucfirst($page))?> · FleetOps</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><aside class="sidebar"><a class="brand" href="?page=dashboard"><img src="assets/fleetops-logo.svg" alt="FleetOps"></a><div class="workspace"><span class="org-dot"><?=e(strtoupper(substr($orgName,0,2)))?></span><span><b><?=e($orgName)?></b><small>Operations workspace</small></span><span class="chevron">⌄</span></div><p class="nav-label">WORKSPACE</p><nav><?php navlink('dashboard','Overview','◫'); navlink('fleet','Fleet','▤'); navlink('assignments','Assignments','⇄'); navlink('maintenance','Maintenance','⚙'); navlink('fuel','Fuel & costs','◉'); navlink('alerts','Alerts','♧',$alertsCount); if(can('FLEET_MANAGER')) navlink('people','People','♙'); ?></nav><div class="sidebar-bottom"><div class="avatar"><?=e(strtoupper(substr($me['name'],0,1)))?></div><span><b><?=e($me['name'])?></b><small><?=e(str_replace('_',' ',strtolower($me['role'])))?></small></span><form method="post" class="logout-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="logout"><button title="Sign out" aria-label="Sign out">↗</button></form></div></aside><main class="main"><header class="topbar"><div class="crumb"><?=e($orgName)?> <span>/</span> <b><?=e(ucfirst($page==='dashboard'?'Overview':str_replace('_',' ',$page)))?></b></div><div class="top-actions"><span class="live"><i></i> System operational</span><span class="date-label"><?=date('D, M j')?></span><div class="avatar small-avatar"><?=e(strtoupper(substr($me['name'],0,1)))?></div></div></header><section class="content">
