</section></main></div></body></html><?php
function navlink(string $id,string $label,string $icon,int $count=0): void { $active=($_GET['page']??'dashboard')===$id?'active':''; echo '<a class="nav-item '.$active.'" href="?page='.$id.'"><span class="nav-icon">'.$icon.'</span>'.$label.($count?'<em>'.$count.'</em>':'').'</a>'; }
function page_head(string $eyebrow,string $title,string $desc,string $action=''): void { echo '<div class="page-head"><div><p class="eyebrow">'.e($eyebrow).'</p><h1>'.e($title).'</h1><p class="muted">'.e($desc).'</p></div>'.$action.'</div>'; }
function render_page(string $page,array $vehicles,array $drivers,array $mechanics): void {
 $org=user()['org_id']; $pdo=db();
 if($page==='dashboard') {
  $stats=one("SELECT COUNT(*) total,SUM(status='ACTIVE') active,SUM(status='DUE_FOR_SERVICE') due,SUM(status='IN_MAINTENANCE') maintenance FROM vehicles WHERE org_id=? AND deleted_at IS NULL",[$org]);
  $jobs=rows("SELECT j.title,j.status,j.opened_at,v.plate_number FROM job_cards j JOIN vehicles v ON v.id=j.vehicle_id WHERE v.org_id=? AND j.status IN ('OPEN','IN_PROGRESS') ORDER BY j.opened_at DESC LIMIT 5",[$org]);
  $upcoming=rows("SELECT a.shift_start,a.shift_end,v.plate_number,v.model,u.name driver FROM assignments a JOIN vehicles v ON v.id=a.vehicle_id JOIN users u ON u.id=a.driver_id WHERE v.org_id=? AND a.shift_end>=NOW() ORDER BY a.shift_start LIMIT 5",[$org]);
  $fuel=one("SELECT COALESCE(SUM(f.total_cost),0) cost,COALESCE(SUM(f.liters),0) liters FROM fuel_logs f JOIN vehicles v ON v.id=f.vehicle_id WHERE v.org_id=? AND f.logged_at >= DATE_FORMAT(CURRENT_DATE,'%Y-%m-01')",[$org]); $alerts=(int)one('SELECT COUNT(*) n FROM alerts WHERE org_id=? AND resolved=0',[$org])['n'];
  page_head(strtoupper(date('l, F j, Y')),'Fleet overview','A clear view of what is moving, what needs attention and what comes next.','<a class="button primary" href="?page=fleet">View fleet <span>→</span></a>');
  echo '<div class="stat-grid"><article class="stat-card"><span class="stat-icon blue">▤</span><span class="stat-label">Total vehicles</span><strong>'.(int)$stats['total'].'</strong><small>Registered in your fleet</small></article><article class="stat-card"><span class="stat-icon green">✓</span><span class="stat-label">Available</span><strong>'.(int)$stats['active'].'</strong><small>Ready for assignment</small></article><article class="stat-card"><span class="stat-icon amber">⚙</span><span class="stat-label">In maintenance</span><strong>'.(int)$stats['maintenance'].'</strong><small>'.(int)$stats['due'].' due for service</small></article><article class="stat-card"><span class="stat-icon red">♧</span><span class="stat-label">Open alerts</span><strong>'.$alerts.'</strong><small>Need your attention</small></article></div>';
  echo '<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Upcoming assignments</h2><p>Shifts scheduled for your team</p></div><a href="?page=assignments">See schedule <span>→</span></a></div>';
  table_start(['VEHICLE','DRIVER','SHIFT','STATUS']);
  foreach($upcoming as $a) echo '<tr><td><b>'.e($a['plate_number']).'</b><small class="cell-sub">'.e($a['model']).'</small></td><td>'.e($a['driver']).'</td><td>'.date('M j · H:i',strtotime($a['shift_start'])).'</td><td><span class="badge green">Scheduled</span></td></tr>';
  table_end(empty($upcoming),'No upcoming shifts','Assign a driver and vehicle to get started.');
  echo '</section><aside class="panel fuel-panel"><div class="panel-head"><div><h2>Fuel this month</h2><p>Recorded fleet spend</p></div><span class="stat-icon blue">◉</span></div><strong class="big-number">LKR '.number_format((float)$fuel['cost'],0).'</strong><small class="muted">'.number_format((float)$fuel['liters'],1).' litres logged</small><a class="text-link" href="?page=fuel">View fuel activity <span>→</span></a></aside></div>';
  echo '<section class="panel"><div class="panel-head"><div><h2>Maintenance queue</h2><p>Open work orders across your fleet</p></div><a href="?page=maintenance">View all <span>→</span></a></div>';
  table_start(['WORK ORDER','VEHICLE','OPENED','STATUS']);
  foreach($jobs as $j) echo '<tr><td><b>'.e($j['title']).'</b></td><td>'.e($j['plate_number']).'</td><td>'.date('M j, Y',strtotime($j['opened_at'])).'</td><td>'.badge($j['status']).'</td></tr>';
  table_end(empty($jobs),'All caught up','There are no open work orders.');
  echo '</section>';
 } elseif($page==='fleet') render_fleet($vehicles);
 elseif($page==='people') render_people(); elseif($page==='assignments') render_assignments($vehicles,$drivers);
 elseif($page==='maintenance') render_maintenance($vehicles,$mechanics); elseif($page==='fuel') render_fuel($vehicles);
 elseif($page==='alerts') render_alerts(); else { page_head('FLEETOPS','Page unavailable','This page is not available.'); }
}
function table_start(array $heads): void { echo '<div class="table-wrap"><table><thead><tr>'; foreach($heads as $h) echo '<th>'.e($h).'</th>'; echo '</tr></thead><tbody>'; }
function table_end(bool $empty=false,string $title='No records yet',string $desc='New records will show here.'): void { if($empty) echo '<tr><td colspan="8"><div class="empty"><b>'.e($title).'</b><small>'.e($desc).'</small></div></td></tr>'; echo '</tbody></table></div>'; }
function badge(string $text): string { $s=strtolower($text); $c=str_contains($s,'active')||str_contains($s,'complete')?'green':(str_contains($s,'due')||str_contains($s,'open')?'amber':(str_contains($s,'maint')||str_contains($s,'progress')?'blue':(str_contains($s,'retired')||str_contains($s,'cancel')?'gray':'green'))); return '<span class="badge '.$c.'">'.e(str_replace('_',' ',$text)).'</span>'; }
function render_fleet(array $vehicles): void { page_head('ASSET REGISTER','Fleet','Maintain a reliable picture of every vehicle in your operation.',can('FLEET_MANAGER')?'<button class="button primary" data-open="vehicle-modal">＋ Add vehicle</button>':''); echo '<div class="toolbar"><input type="search" placeholder="Search by plate or model…" data-filter="vehicle-table"><span class="muted">'.count($vehicles).' vehicles</span></div><section class="panel table-panel">'; table_start(['VEHICLE','STATUS','YEAR / FUEL','ODOMETER','DOCUMENTS','']); foreach($vehicles as $v){echo '<tr data-search-row><td><span class="vehicle-mark">'.e(substr($v['plate_number'],0,2)).'</span><span class="vehicle-name"><b>'.e($v['plate_number']).'</b><small>'.e($v['model']).'</small></span></td><td>'.badge($v['status']).'</td><td>'.e($v['year']).' · '.e($v['fuel_type']).'</td><td>'.number_format((int)$v['current_odometer']).' km</td><td><small>Insurance '.e($v['insurance_expiry']?:'—').'<br>License '.e($v['revenue_lic_expiry']?:'—').'</small></td><td>'; if(can('FLEET_MANAGER')){ echo '<button class="icon-btn" title="Edit vehicle" data-open="vehicle-modal" data-vehicle-id="'.e($v['id']).'" data-plate="'.e($v['plate_number']).'" data-model="'.e($v['model']).'" data-year="'.e($v['year']).'" data-fuel="'.e($v['fuel_type']).'" data-status="'.e($v['status']).'" data-odometer="'.e($v['current_odometer']).'" data-insurance="'.e($v['insurance_expiry']??'').'" data-license="'.e($v['revenue_lic_expiry']??'') .'">✎</button> '; start_form('vehicle_retire'); echo '<input type="hidden" name="id" value="'.e($v['id']).'"><button class="icon-btn" title="Retire vehicle" data-confirm="Retire this vehicle?">↘</button></form>'; } echo '</td></tr>'; } table_end(empty($vehicles),'No vehicles yet','Add a vehicle to start managing your fleet.'); echo '</section>'; if(can('FLEET_MANAGER')) vehicle_modal(); }
function vehicle_modal(): void { ?><dialog id="vehicle-modal"><form method="post" class="modal-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="vehicle_save"><input type="hidden" name="id"><button type="button" class="modal-close" data-close>×</button><p class="eyebrow">FLEET RECORD</p><h2>Add a vehicle</h2><div class="form-grid"><label>Plate number<input name="plate_number" required maxlength="20"></label><label>Model<input name="model" required></label><label>Year<input type="number" name="year" required min="1980" max="<?=date('Y')+1?>"></label><label>Fuel type<select name="fuel_type"><option>DIESEL</option><option>PETROL</option><option>HYBRID</option><option>ELECTRIC</option></select></label><label>Status<select name="status"><option>ACTIVE</option><option>DUE_FOR_SERVICE</option><option>IN_MAINTENANCE</option><option>RETIRED</option></select></label><label>Odometer (km)<input type="number" name="current_odometer" min="0" value="0"></label><label>Insurance expiry<input type="date" name="insurance_expiry"></label><label>Revenue license expiry<input type="date" name="revenue_lic_expiry"></label></div><button class="button primary">Save vehicle</button></form></dialog><?php }
function render_people(): void { $people=rows('SELECT id,name,email,role,created_at FROM users WHERE org_id=? ORDER BY role,name',[user()['org_id']]); page_head('TEAM DIRECTORY','People','Keep your drivers and mechanics in the same loop.','<button class="button primary" data-open="person-modal">＋ Add team member</button>'); echo '<div class="people-grid">'; foreach($people as $p) echo '<article class="person-card"><div class="avatar">'.e(strtoupper(substr($p['name'],0,1))).'</div><div><b>'.e($p['name']).'</b><small>'.e($p['email']).'</small></div>'.badge($p['role']).'</article>'; if(!$people) echo '<div class="empty">No team members found.</div>'; echo '</div><dialog id="person-modal"><form method="post" class="modal-form"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="person_save"><button type="button" class="modal-close" data-close>×</button><p class="eyebrow">TEAM DIRECTORY</p><h2>Add team member</h2><label>Full name<input name="name" required></label><label>Email address<input name="email" type="email" required></label><label>Temporary password<input name="password" type="password" minlength="12" required></label><label>Role<select name="role"><option value="DRIVER">Driver</option><option value="MECHANIC">Mechanic</option></select></label><button class="button primary">Create account</button></form></dialog>'; }
function render_assignments(array $vehicles,array $drivers): void { $sql='SELECT a.*,v.plate_number,v.model,u.name driver FROM assignments a JOIN vehicles v ON v.id=a.vehicle_id JOIN users u ON u.id=a.driver_id WHERE v.org_id=?'; $params=[user()['org_id']]; if(can('DRIVER')){$sql.=' AND a.driver_id=?';$params[]=user()['id'];}$sql.=' ORDER BY a.shift_start DESC LIMIT 100'; $list=rows($sql,$params); page_head('SCHEDULING','Assignments','Coordinate the right driver and vehicle for every shift.',can('FLEET_MANAGER')?'<button class="button primary" data-open="assignment-modal">＋ Schedule shift</button>':''); echo '<section class="panel table-panel">'; table_start(['VEHICLE','DRIVER','START','END']); foreach($list as $a) echo '<tr><td><b>'.e($a['plate_number']).'</b><small class="cell-sub">'.e($a['model']).'</small></td><td>'.e($a['driver']).'</td><td>'.date('M j, Y · H:i',strtotime($a['shift_start'])).'</td><td>'.date('M j, Y · H:i',strtotime($a['shift_end'])).'</td></tr>'; table_end(!$list,'No assignments yet','Schedule a shift to coordinate your team.').'</section>'; if(can('FLEET_MANAGER')) { echo '<dialog id="assignment-modal"><form method="post" class="modal-form"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="assignment_save"><button type="button" class="modal-close" data-close>×</button><p class="eyebrow">NEW SHIFT</p><h2>Schedule assignment</h2><label>Vehicle<select name="vehicle_id" required>'; foreach($vehicles as $v) if($v['status']==='ACTIVE') echo '<option value="'.e($v['id']).'">'.e($v['plate_number'].' · '.$v['model']).'</option>'; echo '</select></label><label>Driver<select name="driver_id" required>'; foreach($drivers as $d) echo '<option value="'.e($d['id']).'">'.e($d['name']).'</option>'; echo '</select></label><label>Shift start<input type="datetime-local" name="shift_start" required></label><label>Shift end<input type="datetime-local" name="shift_end" required></label><button class="button primary">Save assignment</button></form></dialog>'; } }
function render_maintenance(array $vehicles,array $mechanics): void { $sql='SELECT j.*,v.plate_number,u.name mechanic,(SELECT GROUP_CONCAT(CONCAT(p.name,\' × \' ,p.quantity) SEPARATOR \', \') FROM job_parts p WHERE p.job_card_id=j.id) parts FROM job_cards j JOIN vehicles v ON v.id=j.vehicle_id LEFT JOIN users u ON u.id=j.mechanic_id WHERE v.org_id=?'; $params=[user()['org_id']]; if(can('MECHANIC')){$sql.=' AND j.mechanic_id=?';$params[]=user()['id'];}$sql.=' ORDER BY j.opened_at DESC'; $jobs=rows($sql,$params); $rules=rows('SELECT sr.*,v.plate_number,v.current_odometer FROM service_rules sr JOIN vehicles v ON v.id=sr.vehicle_id WHERE v.org_id=? ORDER BY sr.name',[user()['org_id']]); page_head('SERVICE & REPAIRS','Maintenance','Plan service intervals and keep repairs moving.',can('FLEET_MANAGER','MECHANIC')?'<button class="button primary" data-open="job-modal">＋ New job card</button>':''); echo '<div class="subhead"><h2>Job cards</h2><span>'.count($jobs).' records</span></div><section class="panel table-panel">'; table_start(['WORK ORDER','VEHICLE','MECHANIC','LABOR / PARTS','STATUS','UPDATE']); foreach($jobs as $j){echo '<tr><td><b>'.e($j['title']).'</b><small class="cell-sub">'.e($j['description']).'</small>'.($j['parts']?'<small class="cell-sub">Parts: '.e($j['parts']).'</small>':'').'</td><td>'.e($j['plate_number']).'</td><td>'.e($j['mechanic']??'Unassigned').'</td><td>LKR '.number_format((float)$j['labor_cost'],2).'</td><td>'.badge($j['status']).'</td><td>'; if(in_array($j['status'],['OPEN','IN_PROGRESS'],true)&&can('FLEET_MANAGER','MECHANIC')) {start_form('job_status'); echo '<input type="hidden" name="id" value="'.e($j['id']).'"><select name="status"><option value="IN_PROGRESS">In progress</option><option value="COMPLETED">Completed</option><option value="CANCELLED">Cancelled</option></select><button class="mini-button">Update</button></form>'; } echo '</td></tr>'; } table_end(!$jobs,'No job cards','Repairs and service jobs will show here.').'</section><div class="subhead"><h2>Service rules</h2>'.(can('FLEET_MANAGER')?'<button class="button secondary small" data-open="rule-modal">＋ Add rule</button>':'').'</div><section class="panel table-panel">'; table_start(['RULE','VEHICLE','INTERVAL','LAST SERVICE','NEXT SERVICE']); foreach($rules as $r){$next=(int)$r['last_service_odometer']+(int)$r['interval_km']; echo '<tr><td><b>'.e($r['name']).'</b></td><td>'.e($r['plate_number']).'</td><td>'.number_format($r['interval_km']).' km</td><td>'.number_format($r['last_service_odometer']).' km</td><td>'.number_format($next).' km '.((int)$r['current_odometer'] >= $next?'<span class="badge amber">Due</span>':'').'</td></tr>'; } table_end(!$rules,'No service rules','Add a rule to track mileage based service.').'</section>';
 if(can('FLEET_MANAGER','MECHANIC')){echo '<dialog id="job-modal"><form method="post" class="modal-form"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="job_save"><button type="button" class="modal-close" data-close>×</button><p class="eyebrow">SERVICE & REPAIRS</p><h2>Create job card</h2><label>Vehicle<select name="vehicle_id" required>'; vehicle_options($vehicles); echo '</select></label><label>Title<input name="title" required></label><label>Description<textarea name="description" rows="3"></textarea></label><label>Mechanic<select name="mechanic_id"><option value="">Unassigned</option>'; foreach($mechanics as $m) echo '<option value="'.e($m['id']).'">'.e($m['name']).'</option>'; echo '</select></label><label>Service rule<select name="service_rule_id"><option value="">None</option>'; foreach(rows('SELECT sr.id,sr.name,v.plate_number FROM service_rules sr JOIN vehicles v ON v.id=sr.vehicle_id WHERE v.org_id=?', [user()['org_id']]) as $r) echo '<option value="'.e($r['id']).'">'.e($r['plate_number'].' · '.$r['name']).'</option>'; echo '</select></label><label>Labor cost (LKR)<input type="number" name="labor_cost" min="0" step="0.01" value="0"></label><label>Part name (optional)<input name="part_name"></label><div class="form-grid"><label>Part quantity<input type="number" name="part_quantity" min="1" value="1"></label><label>Unit cost (LKR)<input type="number" name="part_cost" min="0" step="0.01" value="0"></label></div><button class="button primary">Create job</button></form></dialog>';
 echo '<dialog id="rule-modal"><form method="post" class="modal-form"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="rule_save"><button type="button" class="modal-close" data-close>×</button><p class="eyebrow">PREVENTIVE CARE</p><h2>Add service rule</h2><label>Vehicle<select name="vehicle_id">'; vehicle_options($vehicles); echo '</select></label><label>Rule name<input name="name" required></label><label>Interval (km)<input type="number" name="interval_km" min="1" required></label><label>Last service odometer<input type="number" name="last_service_odometer" min="0" value="0" required></label><button class="button primary">Save rule</button></form></dialog>'; }
}
function render_fuel(array $vehicles): void { $sql='SELECT f.*,v.plate_number,u.name driver FROM fuel_logs f JOIN vehicles v ON v.id=f.vehicle_id JOIN users u ON u.id=f.driver_id WHERE v.org_id=?'; $params=[user()['org_id']]; if(can('DRIVER')){$sql.=' AND f.driver_id=?';$params[]=user()['id'];}$sql.=' ORDER BY f.logged_at DESC LIMIT 100'; $logs=rows($sql,$params); $sum=one('SELECT COALESCE(SUM(f.total_cost),0) cost,COALESCE(SUM(f.liters),0) liters FROM fuel_logs f JOIN vehicles v ON v.id=f.vehicle_id WHERE v.org_id=? AND f.logged_at>=DATE_FORMAT(CURRENT_DATE,\'%Y-%m-01\')',[user()['org_id']]); page_head('FUEL & COSTS','Fuel activity','Track refuelling, odometer readings and fleet spend.',can('FLEET_MANAGER','DRIVER')?'<button class="button primary" data-open="fuel-modal">＋ Log fuel</button>':''); echo '<div class="fuel-summary"><div class="panel"><span class="muted">Spend this month</span><b>LKR '.number_format((float)$sum['cost'],2).'</b></div><div class="panel"><span class="muted">Fuel logged this month</span><b>'.number_format((float)$sum['liters'],1).' L</b></div><div class="panel"><span class="muted">Entries</span><b>'.count($logs).'</b></div></div><section class="panel table-panel">'; table_start(['DATE','VEHICLE','DRIVER','ODOMETER','LITERS','COST','TANK']); foreach($logs as $l) echo '<tr><td>'.date('M j, Y H:i',strtotime($l['logged_at'])).'</td><td><b>'.e($l['plate_number']).'</b></td><td>'.e($l['driver']).'</td><td>'.number_format($l['odometer']).' km</td><td>'.number_format((float)$l['liters'],1).'</td><td>LKR '.number_format((float)$l['total_cost'],2).'</td><td>'.($l['full_tank']?'Full':'Partial').'</td></tr>'; table_end(!$logs,'No fuel entries','Record the first fill-up to see fleet fuel activity.').'</section>'; if(can('FLEET_MANAGER','DRIVER')){echo '<dialog id="fuel-modal"><form method="post" class="modal-form"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="fuel_save"><button type="button" class="modal-close" data-close>×</button><p class="eyebrow">FUEL LOG</p><h2>Record refuelling</h2><label>Vehicle<select name="vehicle_id">'; vehicle_options($vehicles); echo '</select></label>'; if(can('FLEET_MANAGER')){echo '<label>Driver<select name="driver_id"><option value="">My account</option>'; foreach(rows("SELECT id,name FROM users WHERE org_id=? AND role='DRIVER' ORDER BY name",[user()['org_id']]) as $d) echo '<option value="'.e($d['id']).'">'.e($d['name']).'</option>'; echo '</select></label>'; } echo '<label>Odometer (km)<input name="odometer" type="number" min="0" required></label><label>Litres<input name="liters" type="number" step="0.01" min="0.01" required></label><label>Total cost (LKR)<input name="total_cost" type="number" step="0.01" min="0" required></label><label class="check-label"><input type="checkbox" name="full_tank" checked> Full tank</label><button class="button primary">Save fuel log</button></form></dialog>'; } }
function render_alerts(): void { $alerts=rows('SELECT a.*,v.plate_number FROM alerts a JOIN vehicles v ON v.id=a.vehicle_id WHERE a.org_id=? ORDER BY a.resolved,a.created_at DESC',[user()['org_id']]); page_head('NEEDS ATTENTION','Alerts','Operational reminders for service and document renewals.'); echo '<div class="alert-list">'; foreach($alerts as $a){echo '<article class="panel alert-card"><span class="alert-symbol">'.($a['type']==='SERVICE_DUE'?'⚙':'◷').'</span><div class="alert-copy"><div>'.badge($a['type']).' '.($a['resolved']?'<span class="badge gray">Resolved</span>':'<span class="badge amber">Open</span>').'</div><h3>'.e($a['message']).'</h3><small>'.e($a['plate_number']).' · '.date('M j, Y',strtotime($a['created_at'])).'</small></div>'; if(!$a['resolved']&&can('FLEET_MANAGER')) {start_form('alert_resolve'); echo '<input type="hidden" name="id" value="'.e($a['id']).'"><button class="button secondary small">Resolve</button></form>'; } echo '</article>'; } if(!$alerts) echo '<div class="panel empty">No alerts on your fleet. You are all caught up.</div>'; echo '</div>'; }
